-- Development authority helper; the G runtime patch supplies ordinary walk hooks.
create or replace function ml_private.p3g_haki_escape(s jsonb,a integer,cell text,left_steps integer) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare queue jsonb:=jsonb_build_array(jsonb_build_array(cell,left_steps));node jsonb;best jsonb:='{}';probe jsonb:=s;from_cell text;steps integer;c jsonb;cost integer;begin
 if ml_private.stage4_location_stops(s,a,cell) and ml_private.occupied(s,cell,a) then return false;end if;if not ml_private.occupied(s,cell,a) then return true;end if;
 while jsonb_array_length(queue)>0 loop node:=queue->0;queue:=queue-0;from_cell:=node->>0;steps:=(node->>1)::int;if coalesce((best->>from_cell)::int,-1)>=steps then continue;end if;best:=jsonb_set(best,array[from_cell],to_jsonb(steps));probe:=jsonb_set(probe,array['players',a::text,'cell'],to_jsonb(from_cell));
  for c in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop cost:=ml_private.classic_step_cost(probe,a,c->>'id');if cost is null or cost>steps or ml_private.stage4_location_stops(probe,a,c->>'id') and ml_private.occupied(s,c->>'id',a) or not ml_private.p3f_preview_move(probe,a,c->>'id') or not ml_private.stage3_can_enter(probe,a,c->>'id') then continue;end if;if not ml_private.occupied(s,c->>'id',a) then return true;end if;queue:=queue||jsonb_build_array(jsonb_build_array(c->'id',steps-cost));end loop;
 end loop;return false;end $$;
